/* <grp.h> for porting Unix sources to OS-9/68k.   The disk has this header already, as DEFS/os9lib/grp.h; this only puts it   where a Unix source looks for it.  A forward rather than a copy, and a   NARROW one on purpose: putting DEFS/os9lib on the include path wholesale   shadows the SDK's own <time.h> with a copy that includes </h0/defs/setsys.h>   by absolute path, which no build here has. *//* <stdio.h> FIRST: os9lib/grp.h declares fgetgrent(FILE *), and under a   compiler that defines __GNUC__ it takes its prototype arm, so FILE has to   be known.  gtar names.c includes <grp.h> without <stdio.h> before it and   got `parse error' inside a header it never asked for.  Harmless where   stdio is already in scope. */#include <stdio.h>#include <os9lib/grp.h>